-- PLAN-UNTRUSTED-RECORD-1 (2026-10-19, charter pillar: autonomy). qnfo-code-orchestrator's planner read the 40 highest-priority open
-- issues with no recent plan and skipped an untrusted one (source outside PLAN_TRUSTED) without recording it. Measured 2026-10-19
-- 09:05Z: 39 of the 40 rows in that window were untrusted, so every tick re-read the same rows, and 42 trusted open issues below
-- them were never planned (180 of 195 open issues had no plan). 0.18.28 records outcome 'untrusted' (no model call), which takes the
-- issue out of the window for PLAN_RECHECK_DAYS. Detector: no open issue the planner reads (no code-task line) is older than 120
-- minutes with no issue_plans row while its source is untrusted.
-- APPLY-BY: ci
-- DB: qnfo-audit
-- Rollback: DELETE FROM remediation_contracts WHERE class = 'fm-code-plan-untrusted-starves'; DELETE FROM failure_modes WHERE fm_key = 'code-plan-untrusted-starves'

INSERT OR IGNORE INTO failure_modes (fm_key, failure_mode, root_cause, remediation, detector, probe_class, first_seen, issue_id, trigger_condition, symptom, blast_radius) VALUES
 ('code-plan-untrusted-starves', 'untrusted issues fill the code-loop planner''s priority window and trusted issues behind them are never planned', 'planIssues skipped an untrusted issue with a bare continue, so it stayed in the 40-row window (LIMIT 40, no plan row) at every tick', 'qnfo-code-orchestrator 0.18.28 PLAN-UNTRUSTED-RECORD-1: the planner records outcome untrusted, so the issue leaves the window for PLAN_RECHECK_DAYS', 'fm-code-plan-untrusted-starves: open issues without a code-task line, older than 120 minutes, untrusted and with no issue_plans row', 'fm-code-plan-untrusted-starves', '2026-10-18T12:12:09Z', NULL, '40 or more untrusted open issues rank above a trusted one', 'issue_plans gains few rows while most open issues have none; trusted issues sit unplanned', 'code loop: every trusted open issue below the window (42 on 2026-10-19)');
INSERT OR IGNORE INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status, next_due_at, module, budget_ms, max_items, requires_container) VALUES
 ('fm-code-plan-untrusted-starves', NULL, 'PLAN-UNTRUSTED-RECORD-1', 'failure-mode detector', 'SELECT ''0'' AS expected, CAST((SELECT COUNT(*) FROM agent_issues a WHERE a.status = ''open'' AND COALESCE(a.description, '''') NOT LIKE ''%code-task:%'' AND a.created_at < (CAST(strftime(''%s'', ''now'') AS INTEGER) - 7200) * 1000 AND NOT EXISTS (SELECT 1 FROM issue_plans p WHERE p.issue_id = a.id) AND NOT ((a.source = ''qnfo-fleet-dashboard:owner-request'' AND (a.title LIKE ''OWNER-TASK-%'' OR a.title LIKE ''OWNER-NOTE-%'')) OR (a.source = ''qnfo-fleet-control'' AND (a.title LIKE ''METRIC-TRIGGER-%'' OR a.title LIKE ''REACH-IDEA-%'')) OR a.source LIKE ''claude-session%'' OR a.source LIKE ''claude-code-session%'')) AS TEXT) AS observed', 'd1-query', 3, 'qnfo-code-orchestrator', 1, 'active', strftime('%Y-%m-%d %H:%M:%S', 'now'), 'failure-mode', 45000, 5, 0);
